INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoarthritis — Diagnosis & Management','easy','flashcard','Name the four cardinal radiographic features of osteoarthritis (mnemonic: LOSS).','["Loss of joint space (asymmetric narrowing), Osteophytes (bony spurs), Subchondral sclerosis, Subchondral cysts"]','A','The mnemonic LOSS helps recall the four hallmark X-ray findings of OA: Loss of joint space (asymmetric), Osteophytes (periarticular bony spurs), Subchondral Sclerosis (cortical thickening), and Subchondral cysts. These contrast with RA (periarticular osteopenia and erosions).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoarthritis — Diagnosis & Management','easy','flashcard','What are Heberden''s nodes and Bouchard''s nodes, and where do they occur?','["Heberden''s nodes = osteophytes at DIP joints; Bouchard''s nodes = osteophytes at PIP joints — both characteristic of hand osteoarthritis"]','A','Heberden''s nodes are bony enlargements (osteophytes) at the DIP joints; Bouchard''s nodes at the PIP joints. Both are features of primary generalised OA affecting the hands. DIP involvement distinguishes OA from RA (which spares DIPs).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoarthritis — Diagnosis & Management','easy','flashcard','What is the first-line pharmacological treatment for mild-to-moderate OA pain?','["Paracetamol (acetaminophen) — safest analgesic with fewest systemic side effects for initial OA pain management"]','A','Paracetamol is recommended as first-line analgesia for OA. NSAIDs are second-line due to GI, cardiovascular, and renal risks. Opioids are reserved for refractory severe pain. Topical NSAIDs (diclofenac gel) are preferred over oral NSAIDs when possible to reduce systemic risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoarthritis — Diagnosis & Management','medium','flashcard','How does synovial fluid in non-inflammatory OA differ from inflammatory arthritis on analysis?','["Non-inflammatory OA: WBC <2000 cells/µL, predominantly mononuclear, clear/straw-coloured, high viscosity. Inflammatory: WBC 2000–50,000 (RA, crystal); Septic: >50,000 cells/µL with PMN predominance"]','A','Synovial fluid classification: non-inflammatory (<2000 WBC, clear, high viscosity — OA, trauma); inflammatory (2000–50,000 WBC, turbid — RA, gout, pseudogout); septic (>50,000 WBC, >90% PMNs, positive culture). This triage guides urgent management.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoarthritis — Diagnosis & Management','medium','flashcard','What is the role of intra-articular corticosteroid injection in OA management?','["Short-term (weeks) pain relief for monoarticular flare with effusion; does not modify disease; repeated injections may accelerate cartilage damage — use sparingly (≤3–4 per year per joint)"]','A','Intra-articular corticosteroids provide rapid but temporary (weeks to 3 months) pain relief in OA flares with effusion. They are useful as a bridge while other treatments are optimised. They should not replace physiotherapy or weight loss and should be limited in frequency.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoarthritis — Diagnosis & Management','medium','flashcard','What does Harrison''s say about delaying total joint replacement until advanced functional decline in OA?','["Postoperative functional status may not recover to the level achievable by those who underwent surgery earlier — early surgical timing when severe OA but before profound muscle wasting optimises outcomes"]','A','Harrison''s explicitly states that patients who suffer for many years until functional status has declined substantially, with considerable muscle weakness, may not achieve the same postoperative outcomes as those operated on earlier. Timing of joint replacement should balance readiness with avoiding excessive functional deterioration.','universal',true,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoarthritis — Diagnosis & Management','hard','flashcard','What is the role of the quadriceps muscle in protecting the knee joint in OA?','["Quadriceps contraction decelerates the joint before impact and distributes load across the cartilage — weakness leads to focal stress, accelerating OA progression; strengthening is the most evidence-based non-pharmacological intervention"]','A','Joint protection in OA relies on muscle-tendon units bridging the joint. The quadriceps in particular decelerates the knee before heel-strike and distributes forces broadly. Quadriceps weakness (common in OA) increases focal cartilage loading, worsening OA. Exercise therapy targets this mechanism.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoarthritis — Diagnosis & Management','easy','flashcard','Which joints are most commonly affected by primary OA?','["Knees, hips, DIP and PIP joints of hands, first CMC joint (base of thumb), first MTP joint, and lumbar/cervical facet joints"]','A','Primary OA predominantly affects weight-bearing joints (knees, hips) and the small joints of the hands (DIPs — Heberden''s, PIPs — Bouchard''s, first CMC — ''squaring'' of the thumb base). The first MTP joint and facet joints of the spine are also common. Wrists and MCPs are typically spared (suggesting RA if involved).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoarthritis — Diagnosis & Management','hard','flashcard','What is the significance of matrix metalloproteinases (MMPs) and ADAMTS-5 in OA pathogenesis?','["MMPs (collagenases) and ADAMTS-5 (aggrecanase) are key enzymes that break down cartilage matrix — collagen and aggrecan respectively — with catabolic activity exceeding synthetic activity, leading to progressive cartilage loss in OA"]','A','In OA, chondrocytes synthesise elevated levels of MMPs and ADAMTS-5 under cytokine stimulation (IL-1β, TNF-α from synovium). These enzymes degrade collagen and aggrecan (the proteoglycan that gives cartilage its compressive resistance). The resulting matrix breakdown exceeds repair capacity, causing progressive OA.','universal',false,'{year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoarthritis — Diagnosis & Management','medium','flashcard','What is the difference in morning stiffness between OA and rheumatoid arthritis?','["OA: morning stiffness <30 minutes (''gelling''), worsens with activity; RA: morning stiffness >1 hour, improves with activity"]','A','This classic distinction is clinically useful: OA stiffness is brief (<30 min), worsens with use (activity pain), and improves with rest. RA stiffness is prolonged (>1 hour), reflects synovial inflammation accumulating during rest, and improves with movement. This helps differentiate mechanical from inflammatory arthritis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Rheumatoid Arthritis — Diagnosis & Management','easy','flashcard','What are the 2010 ACR/EULAR classification criteria domains for RA, and what score is required?','["Four domains: joint involvement (0–5), serology RF/anti-CCP (0–3), acute-phase reactants CRP/ESR (0–1), symptom duration (0–1); score ≥6/10 classifies RA"]','A','The 2010 criteria replaced the 1987 criteria to enable earlier diagnosis. They allow classification before erosions develop. Joint involvement is scored by number and size of affected joints; serology includes both low-positive and high-positive RF/anti-CCP; duration ≥6 weeks scores 1.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Rheumatoid Arthritis — Diagnosis & Management','easy','flashcard','Which serology marker is most specific for RA and why?','["Anti-CCP (anti-cyclic citrullinated peptide) — >95% specific for RA; detects antibodies to citrullinated proteins, can be positive years before symptoms, predicts erosive disease"]','A','Anti-CCP antibodies are generated against citrullinated proteins (modified by PAD4 enzyme in RA synovium). They are highly specific (>95%) and can precede clinical onset by years. Positive anti-CCP plus RF (double seropositivity) predicts more severe, erosive disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Rheumatoid Arthritis — Diagnosis & Management','easy','flashcard','What is the anchor DMARD for RA and what monitoring is required?','["Methotrexate is the anchor DMARD; monitoring: FBC (myelosuppression), LFTs (hepatotoxicity), renal function (excretion), CXR (pulmonary toxicity); co-prescribe folic acid 5 mg/week to reduce side effects"]','A','Methotrexate is the cornerstone of RA treatment. Its toxicity profile requires regular monitoring: monthly FBC, LFTs, and renal function initially, reducing to every 3 months when stable. Folic acid co-prescription reduces mucositis, nausea, and cytopaenia without reducing efficacy.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Rheumatoid Arthritis — Diagnosis & Management','medium','flashcard','Explain treat-to-target (T2T) strategy in RA management.','["Treat-to-target: set explicit goal of remission or low disease activity; assess disease activity (DAS28) monthly; escalate treatment every 3–6 months if target not reached; prevents joint damage"]','A','T2T is the standard of care in RA. Using validated tools (DAS28, CDAI, SDAI), disease activity is formally measured at each visit. Treatment is escalated stepwise (csDMARDs → combination → bDMARDs → JAK inhibitors) until remission or low disease activity is sustained.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Rheumatoid Arthritis — Diagnosis & Management','medium','flashcard','Why is methotrexate contraindicated in pregnancy, and what RA drug is preferred during pregnancy?','["Methotrexate is a folate antagonist — teratogenic (neural tube defects, embryopathy) — must stop ≥3 months before conception. Preferred options: hydroxychloroquine, sulfasalazine, low-dose prednisolone; certolizumab pegol preferred biologic (does not cross placenta)"]','A','MTX is an absolute contraindication in pregnancy and breastfeeding. Leflunomide is also teratogenic. During pregnancy, low-disease-activity RA can be managed with HCQ, sulfasalazine, or prednisolone. Certolizumab pegol (no Fc region — minimal placental transfer) is the biologic of choice when needed.','universal',true,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Rheumatoid Arthritis — Diagnosis & Management','medium','flashcard','What is atlantoaxial subluxation in RA and why is it clinically important?','["C1–C2 instability from erosion of the transverse ligament and odontoid process — can compress the spinal cord/medulla; risk during anaesthetic intubation (neck extension); requires flexion-extension cervical X-ray or MRI before surgery"]','A','In longstanding seropositive RA, pannus erodes the transverse ligament holding the odontoid peg of C2, causing C1 to slide forward on C2 (atlantoaxial subluxation). This is dangerous during intubation (neck extension). Screening with flexion-extension cervical X-ray is mandatory before elective procedures requiring general anaesthesia.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Rheumatoid Arthritis — Diagnosis & Management','hard','flashcard','Name three extra-articular manifestations of RA and their clinical significance.','["Rheumatoid nodules (over pressure points — benign but indicate seropositive disease); Pulmonary involvement (ILD, nodules, pleuritis — leading cause of mortality); Vasculitis (digital infarcts, mononeuritis multiplex — indicates severe disease requiring aggressive treatment)"]','A','Extra-articular RA reflects systemic vasculitis and immune complex deposition. Rheumatoid nodules (subcutaneous, over olecranon, sacrum) indicate high RF. Pulmonary ILD is a major cause of RA mortality. Cardiac (pericarditis, IHD acceleration), renal (amyloidosis), and ocular (scleritis) involvement also occur.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Rheumatoid Arthritis — Diagnosis & Management','easy','flashcard','What is the DMARD step-up sequence in RA management?','["Step 1: Methotrexate monotherapy; Step 2: Combination csDMARDs (MTX + hydroxychloroquine ± sulfasalazine); Step 3: Add biologic (TNF inhibitor, IL-6 inhibitor, abatacept) or JAK inhibitor if inadequate response"]','A','The treat-to-target DMARD step-up: MTX is started first (± short-term bridging steroids); if insufficient at 3–6 months, add HCQ or sulfasalazine; if still insufficient, escalate to bDMARDs (anti-TNF, tocilizumab, abatacept) or tsDMARDs (JAK inhibitors: baricitinib, upadacitinib).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Rheumatoid Arthritis — Diagnosis & Management','hard','flashcard','What is the mechanism of action of TNF inhibitors in RA?','["TNF inhibitors (etanercept, adalimumab, infliximab, certolizumab, golimumab) bind and neutralise soluble and/or membrane-bound TNF-α, blocking downstream NF-κB signalling, reducing synovial inflammation, pannus formation, and osteoclast-mediated bone erosion"]','A','TNF-α is a key pro-inflammatory cytokine in RA synovium. Blocking TNF reduces IL-6, IL-1, and MMP production, controlling inflammation and preventing joint destruction. Risks include reactivation of latent TB (screen with IGRA/Mantoux before starting) and increased susceptibility to infections.','universal',true,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Rheumatoid Arthritis — Diagnosis & Management','medium','flashcard','What joint deformities are characteristically seen in longstanding RA of the hands?','["Ulnar deviation at MCPs, swan-neck deformity (PIP hyperextension, DIP flexion), boutonnière deformity (PIP flexion, DIP hyperextension), and Z-deformity of thumb — all from synovitis-induced tendon imbalance"]','A','These hand deformities result from chronic synovitis stretching tendons and ligaments: ulnar drift at MCPs from extensor tendon slipping ulnarly; swan-neck from intrinsic muscle tightening; boutonnière from central slip rupture. Z-deformity (90° flexion at MCP, hyperextension at IP) affects the thumb.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Gout — Acute & Chronic Management','easy','flashcard','What crystal type and microscopic appearance confirms a diagnosis of gout on joint aspiration?','["Monosodium urate (MSU) crystals: needle-shaped (acicular), negatively birefringent (yellow when parallel to compensator axis) on polarised light microscopy — seen within neutrophils during acute attack"]','A','Joint aspiration is the gold standard for gout diagnosis. MSU crystals are long, needle-shaped, and show strong negative birefringence — appearing yellow when the long axis is parallel to the red compensator. During acute attacks, crystals are often phagocytosed by neutrophils (intracellular).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Gout — Acute & Chronic Management','easy','flashcard','According to the Ghana STG 2017, what is the 1st-line treatment for acute gout in adults?','["Diclofenac oral 50 mg 8-hourly or 75 mg 12-hourly (Evidence Rating C); 2nd line: Colchicine 500 mcg 6–12 hourly (max 6 mg/course); give PPI (omeprazole) with NSAIDs >2 weeks"]','A','The Ghana STG 2017 (section 230) designates diclofenac as first-line for acute gout. Colchicine is 2nd-line, limited to max 6 mg per course not repeated within 3 days. Prednisolone 10–40 mg daily for 1–3 days is an alternative. Allopurinol must NOT be started during acute attack.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Gout — Acute & Chronic Management','medium','flashcard','What is the Ghana STG 2017 protocol for chronic gout urate-lowering therapy using allopurinol?','["Start allopurinol 100 mg/day after inflammation resolves (1–2 weeks); increase by 100 mg every 2–5 weeks until SUA <300 µmol/L; max 900 mg; reduce dose in renal/hepatic failure"]','A','The Ghana STG 2017 titration of allopurinol: start low (100 mg/day), titrate upward cautiously every 2–5 weeks with SUA monitoring until target SUA <300 µmol/L. Allopurinol inhibits xanthine oxidase, the enzyme converting xanthine to uric acid. Dose reduction is essential in renal impairment.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Gout — Acute & Chronic Management','medium','flashcard','Why must allopurinol NOT be started during an acute gout attack?','["Acute changes in serum uric acid (either rise or fall) can mobilise urate crystals from joints/tophi, precipitating a new or prolonged flare. Allopurinol should only begin 1–2 weeks after full resolution of inflammation"]','A','Abrupt lowering of serum uric acid during an acute attack destabilises established urate crystal deposits, paradoxically triggering or prolonging joint inflammation. The Ghana STG caution (22-5) explicitly warns against this. Patients already established on allopurinol should continue it during a flare.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Gout — Acute & Chronic Management','medium','flashcard','According to Harrison''s, how long should colchicine prophylaxis be continued when starting urate-lowering therapy?','["Until patient is normouricemic (SUA <300 µmol/L) AND has had no gouty attacks for 6 months — or as long as tophi are present; dose: colchicine 0.6 mg once or twice daily"]','A','Initiating allopurinol can paradoxically trigger gout flares by mobilising crystal deposits. Prophylactic low-dose colchicine (0.6 mg OD-BD) bridges this risk period. Harrison''s specifies the endpoint as normouricaemic with 6 months attack-free, or longer if tophi are present.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Gout — Acute & Chronic Management','hard','flashcard','Which drug classes listed in the Ghana STG 2017 can precipitate gout by impairing uric acid excretion?','["Thiazide diuretics (e.g., hydrochlorothiazide), loop diuretics (e.g., furosemide), cytotoxic drugs, and pyrazinamide (TB treatment) — review medications in all new gout presentations"]','A','The Ghana STG 2017 lists these drugs as causes of impaired uric acid excretion leading to secondary gout. This is clinically important in Ghana given high use of furosemide for heart failure and hydrochlorothiazide for hypertension. Switching to losartan (uricosuric) or amlodipine may be preferable in hypertensive gout patients.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Gout — Acute & Chronic Management','easy','flashcard','Where do tophi characteristically deposit in chronic tophaceous gout?','["Helix of the ear, fingers, toes, olecranon bursa, prepatellar bursa, and Achilles tendon — visible as chalky white nodules under the skin"]','A','Tophi are aggregates of MSU crystals surrounded by granulomatous tissue. They indicate longstanding uncontrolled hyperuricaemia and cause joint destruction, nerve compression, and secondary infection. The Ghana STG lists these characteristic sites. Effective urate-lowering therapy dissolves tophi over months to years.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Gout — Acute & Chronic Management','medium','flashcard','List four non-pharmacological recommendations for gout management per the Ghana STG 2017.','["1) Reduce purine-rich foods (liver, kidneys, shellfish); 2) Reduce alcohol <14 units/week; 3) Drink >2 litres water daily; 4) Avoid highly sweetened soft drinks; elevate and cool affected joint; moderate exercise"]','A','The Ghana STG 2017 emphasises lifestyle modification as integral to gout management: dietary purines increase uric acid production; alcohol reduces renal excretion; dehydration concentrates urate. Fructose-sweetened drinks raise uric acid. Weight loss reduces insulin resistance which impairs urate excretion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Gout — Acute & Chronic Management','hard','flashcard','What is the mechanism of action of colchicine in gout?','["Colchicine binds tubulin and inhibits microtubule polymerisation, impairing neutrophil migration, phagocytosis of urate crystals, and NLRP3 inflammasome activation — reducing IL-1β release and acute inflammatory response"]','A','Colchicine''s anti-inflammatory mechanism is unique — it does not affect uric acid levels. By disrupting microtubule assembly, it prevents neutrophil chemotaxis into the joint and blocks the NLRP3 inflammasome-mediated IL-1β production triggered by MSU crystal phagocytosis. Side effects: diarrhoea, nausea, myelosuppression.','universal',false,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Gout — Acute & Chronic Management','hard','flashcard','Can serum uric acid be normal during an acute gout attack? What does this mean diagnostically?','["Yes — serum uric acid may be normal or even low during acute attacks due to uricosuric effects of acute illness and cytokines. Normal SUA does not exclude gout. Definitive diagnosis requires joint aspiration and crystal identification"]','A','The Ghana STG explicitly states gout may be present even when serum uric acid is normal. Conversely, hyperuricaemia alone does not confirm gout. The gold standard remains synovial fluid analysis showing negatively birefringent needle-shaped MSU crystals on polarised microscopy.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoporosis — Screening & Management','easy','flashcard','What T-score values define normal bone density, osteopenia, and osteoporosis by WHO criteria?','["Normal: T-score > −1.0; Osteopenia: −1.0 to −2.5; Osteoporosis: ≤ −2.5; Severe osteoporosis: ≤ −2.5 with fragility fracture"]','A','T-score compares BMD to a young healthy adult reference (peak bone mass). The Z-score compares to age-matched controls. On DEXA, the hip (femoral neck or total) and lumbar spine (L1–L4) are the standard measurement sites. The lowest T-score at either site is used for diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoporosis — Screening & Management','easy','flashcard','What are the key risk factors for osteoporosis assessed by the FRAX tool?','["Age, sex, BMI, previous fragility fracture, parental hip fracture, current smoking, glucocorticoid use (>5 mg prednisolone daily ≥3 months), rheumatoid arthritis, secondary osteoporosis, alcohol ≥3 units/day, and BMD (optional)"]','A','FRAX calculates 10-year probability of major osteoporotic fracture (hip, spine, wrist, humerus) and hip fracture. It is validated for use without BMD but is more accurate when BMD is included. Country-specific intervention thresholds are applied.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoporosis — Screening & Management','medium','flashcard','What are the administration instructions for oral bisphosphonates (e.g., alendronate) and why?','["Take fasting with 200 mL plain water, 30–60 minutes before any food, drink, or medication; remain upright for 30 minutes; never take lying down — prevents oesophageal erosions and maximises absorption (bioavailability <1% without these precautions)"]','A','Bisphosphonates are poorly absorbed (bioavailability <1% orally). Food, milk, and most drinks impair absorption further. Oesophageal irritation and erosion can occur if tablets dissolve in the oesophagus — patients must remain upright and not eat for 30 minutes. Non-adherence to these instructions is the most common cause of treatment failure.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoporosis — Screening & Management','medium','flashcard','What serious complication of long-term bisphosphonate therapy requires dental screening before starting?','["Osteonecrosis of the jaw (ONJ) — avascular necrosis of jaw bone, particularly after dental extractions or implants; risk increases with IV bisphosphonates (oncology doses), poor dental hygiene, dental procedures"]','A','ONJ presents as exposed jaw bone lasting >8 weeks. Risk is low with oral bisphosphonates for osteoporosis (1:10,000–1:100,000 per year) but significantly higher with IV zoledronic acid or denosumab in cancer patients. Dental review and treatment of active dental disease should be completed before starting bisphosphonates.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoporosis — Screening & Management','medium','flashcard','What is atypical femoral fracture and how is it related to bisphosphonates?','["Transverse, low-energy subtrochanteric or femoral shaft fracture associated with long-term bisphosphonate use; may be bilateral; prodromal thigh/groin pain; mechanism: over-suppression of bone remodelling impairing microcrack repair"]','A','Bisphosphonates suppress osteoclast-mediated bone remodelling. Long-term suppression may impair the normal microcrack repair process, predisposing to ''frozen'' bone that accumulates stress fractures. Guidelines recommend bisphosphonate holiday after 3–5 years for lower-risk patients to allow bone remodelling recovery.','universal',true,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoporosis — Screening & Management','hard','flashcard','What is the mechanism of denosumab and its key advantage over bisphosphonates?','["Denosumab is a monoclonal antibody against RANKL, inhibiting osteoclast differentiation and survival; reduces bone resorption; advantage: safe in renal failure (unlike bisphosphonates which accumulate in CKD), given 60 mg SC every 6 months"]','A','RANKL (receptor activator of NF-κB ligand) is expressed by osteoblasts and essential for osteoclast formation. Denosumab blocks RANKL, reducing osteoclast activity without being incorporated into bone (unlike bisphosphonates). It can be used in CKD where bisphosphonates are contraindicated, but must be given regularly — discontinuation causes rapid rebound bone loss.','universal',false,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoporosis — Screening & Management','hard','flashcard','How does teriparatide differ from bisphosphonates in its mechanism for treating osteoporosis?','["Teriparatide (recombinant PTH 1-34) is anabolic — stimulates osteoblast activity and new bone formation; bisphosphonates are anti-resorptive — inhibit osteoclast activity; teriparatide is used for severe osteoporosis or failure of anti-resorptives; given as daily SC injection for ≤2 years"]','A','Unlike anti-resorptive agents, teriparatide actually increases bone mass by stimulating osteoblastogenesis. When given intermittently (daily SC), PTH favours bone formation over resorption. It is reserved for severe osteoporosis (multiple vertebral fractures, very low T-score) and is followed by anti-resorptive therapy to preserve gains.','universal',false,'{year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoporosis — Screening & Management','easy','flashcard','What supplementation is recommended for all patients on long-term corticosteroids to protect bone?','["Calcium 1000–1300 mg/day AND Vitamin D 200–800 IU/day as standard supplementation; add bisphosphonate for moderate-to-high fracture risk or if DEXA shows osteoporosis"]','A','Glucocorticoids cause bone loss through multiple mechanisms: reducing intestinal calcium absorption, increasing renal calcium excretion, suppressing osteoblast function, and reducing sex hormones. Calcium and vitamin D supplementation are the baseline intervention; the Ghana STG recommends these doses for all fracture risk categories in steroid users.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoporosis — Screening & Management','medium','flashcard','Which women should be screened for osteoporosis with DEXA according to standard guidelines?','["All postmenopausal women aged ≥65 years; postmenopausal women <65 with risk factors (fragility fracture, long-term steroids, low BMI, smoking, family history of hip fracture, secondary causes); men aged ≥70 or with risk factors"]','A','Routine DEXA screening is recommended from age 65 for women and 70 for men. Younger patients are screened if they have significant risk factors. Fragility fracture itself mandates DEXA and treatment regardless of T-score, as it indicates bone fragility exceeding structural capacity.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Osteoporosis — Screening & Management','hard','flashcard','What is the Ghana STG 2017 classification of fracture risk for osteoporosis management?','["Low fracture risk: calcium + vitamin D only; Moderate fracture risk: calcium + vitamin D; High fracture risk: specialist-guided therapy including bisphosphonates, HRT, calcitonin, SERMs, denosumab, strontium, or teriparatide — all cases referred to physician/orthopaedic specialist"]','A','The Ghana STG 2017 takes a tiered approach to osteoporosis based on fracture risk. All cases with high fracture risk are referred to a specialist. The list of agents for high fracture risk reflects the same global guidelines (bisphosphonates 1st-line; others for special cases). All cases with osteoporosis require specialist referral.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','SLE — Diagnosis & Management','easy','flashcard','What are the 1997 ACR classification criteria for SLE? How many must be met?','["11 criteria — need ≥4: malar rash, discoid rash, photosensitivity, oral ulcers, arthritis, serositis, renal disorder (proteinuria/casts), neurological disorder, haematological disorder, immunological disorder (anti-dsDNA/anti-Sm), positive ANA"]','A','The 1997 ACR criteria (update of 1982 criteria) require 4 of 11 criteria, serially or simultaneously. The newer 2019 EULAR/ACR criteria use a weighted score system. In clinical practice, SLE diagnosis is based on clinician judgement integrating all findings — the criteria are primarily classification tools for research.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','SLE — Diagnosis & Management','easy','flashcard','Why is hydroxychloroquine considered the cornerstone of SLE treatment?','["HCQ reduces disease flares, prevents organ damage, reduces cardiovascular risk and thrombosis, improves survival, and is safe in pregnancy; prescribed to ALL SLE patients without contraindication; annual ophthalmology review for retinal toxicity"]','A','Multiple RCTs and registry data show HCQ significantly reduces organ damage accrual, hospitalisation, and mortality in SLE. It is immunomodulatory (interferes with TLR signalling and antigen presentation), anti-thrombotic, and lipid-lowering. The main risk is irreversible retinal toxicity with cumulative high doses.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','SLE — Diagnosis & Management','medium','flashcard','How are complement levels (C3, C4) used in monitoring SLE disease activity?','["C3 and C4 fall during active SLE due to consumption by immune complex deposition; rising anti-dsDNA titre + falling C3/C4 = impending flare, particularly lupus nephritis; useful serial biomarker alongside urinalysis and anti-dsDNA"]','A','In SLE, immune complexes containing anti-dsDNA activate complement via the classical pathway, consuming C3 and C4. Low complement correlates with disease activity, especially nephritis. Sequential monitoring of complement + anti-dsDNA + urine protein:creatinine ratio guides treatment escalation.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','SLE — Diagnosis & Management','medium','flashcard','What is the treatment for Class IV diffuse proliferative lupus nephritis?','["Induction: high-dose corticosteroids + cyclophosphamide (Euro-lupus or NIH protocol) OR mycophenolate mofetil (MMF — preferred in Black patients); Maintenance: MMF or azathioprine; target remission (proteinuria <500 mg/day, stable eGFR)"]','A','Class IV is the most severe and common class of lupus nephritis. Without treatment, it rapidly progresses to renal failure. MMF (3 g/day induction) has equivalent efficacy to cyclophosphamide with fewer side effects (less gonadotoxicity, alopecia) and is preferred in most patients. Regular urine monitoring is essential.','universal',true,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','SLE — Diagnosis & Management','medium','flashcard','What is hydroxychloroquine retinopathy and how is it monitored?','["Bull''s-eye maculopathy — parafoveal photoreceptor loss causing irreversible central visual loss; risk increases with dose >5 mg/kg/day, duration >5 years, renal impairment; annual ophthalmology review with 10-2 visual field and macular OCT from year 5"]','A','HCQ accumulates in melanin-containing retinal pigment epithelium, causing toxicity. Early HCQ toxicity may be asymptomatic, detectable only on OCT and visual fields before patients notice symptoms. Annual screening is mandatory from year 5 (or earlier in high-risk patients — renal disease, tamoxifen co-use).','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','SLE — Diagnosis & Management','hard','flashcard','What is Libman-Sacks endocarditis and how does it relate to SLE?','["Non-infectious verrucous endocarditis of mitral/aortic valve leaflets — both surfaces — associated with antiphospholipid antibodies in SLE; risk of systemic thromboembolism, valve regurgitation, superimposed infective endocarditis; anticoagulation may be required"]','A','Libman-Sacks is the cardiac manifestation of SLE/antiphospholipid syndrome. Unlike rheumatic fever (affects mitral valve undersurface only), it affects both surfaces. The vegetations are small, flat, and rarely cause haemodynamic compromise acutely but carry long-term embolic risk.','universal',false,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','SLE — Diagnosis & Management','hard','flashcard','Define antiphospholipid syndrome (APS) and its diagnostic criteria.','["APS = arterial or venous thrombosis and/or pregnancy morbidity (recurrent losses, stillbirth, premature birth) + persistent antiphospholipid antibodies (lupus anticoagulant, anticardiolipin IgG/IgM, anti-β2-GP1) on ≥2 occasions ≥12 weeks apart"]','A','Primary APS occurs without underlying disease; secondary APS occurs in SLE. Management: long-term anticoagulation (warfarin) for thrombotic APS; low-dose aspirin for obstetric APS; LMWH + aspirin during pregnancy. INR target 2–3 (or 3–4 for recurrent arterial events in some guidelines).','universal',true,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','SLE — Diagnosis & Management','easy','flashcard','Which haematological abnormalities are part of the SLE ACR classification criteria?','["Haemolytic anaemia with reticulocytosis; OR leucopaenia <4000/µL; OR lymphopaenia <1000/µL; OR thrombocytopaenia <100,000/µL (in absence of offending drugs)"]','A','SLE can cause autoimmune cytopaenias through antibody-mediated destruction of red cells (haemolytic anaemia — positive Coombs), white cells, lymphocytes, and platelets. The Ghana STG lists leucopaenia, lymphopaenia, and thrombocytopaenia as haematological complications of SLE.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','SLE — Diagnosis & Management','medium','flashcard','What is the significance of anti-Sm and anti-dsDNA antibodies in SLE?','["Anti-Sm: highly specific for SLE (~25% sensitivity, >99% specific); Anti-dsDNA: high specificity (>95%), correlates with disease activity and lupus nephritis — rising titres precede flares; both are immunological criteria in ACR classification"]','A','Anti-Sm (anti-Smith) and anti-dsDNA are the most SLE-specific antibodies. Anti-dsDNA is dynamic — levels rise with disease flares, particularly nephritis — making it a useful monitoring tool. Anti-Sm is static and does not correlate with activity. ANA is highly sensitive (>95%) but not specific.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','SLE — Diagnosis & Management','hard','flashcard','List three pulmonary complications of SLE and their clinical features.','["1) Pleuritis/pleural effusion (exudate — chest pain, dyspnoea); 2) Pneumonitis (acute lupus pneumonitis — fever, cough, hypoxia; resembles pneumonia); 3) Pulmonary hypertension (progressive dyspnoea, right heart failure — worse prognosis); 4) Shrinking lung syndrome (diaphragm dysfunction)"]','A','Pulmonary involvement in SLE ranges from common (pleuritis — 30–50%) to rare and severe (diffuse alveolar haemorrhage — life-threatening). Distinguishing lupus pneumonitis from infection is critical as both cause fever, infiltrates, and hypoxia — but one requires immunosuppression and the other antibiotics.','universal',false,'{year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Seronegative Spondyloarthropathies','easy','flashcard','What are the four seronegative spondyloarthropathies (SpA)?','["1) Ankylosing spondylitis (AS); 2) Psoriatic arthritis (PsA); 3) Reactive arthritis (formerly Reiter''s syndrome); 4) Enteropathic arthritis (IBD-associated) — all HLA-B27 associated, RF/ANA negative, axial and peripheral involvement, enthesitis"]','A','Seronegative SpA share: absent RF, HLA-B27 association, axial inflammation (sacroiliitis), peripheral asymmetric arthritis, enthesitis, and extra-articular features (uveitis, psoriasis, IBD, urethritis). They are grouped together due to shared pathophysiology involving IL-17/IL-23 axis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Seronegative Spondyloarthropathies','easy','flashcard','What are the characteristic features of inflammatory back pain (distinguishing it from mechanical back pain)?','["Age <45 at onset, insidious onset, duration >3 months, improvement with exercise (not rest), morning stiffness >30 min, alternating buttock pain, improvement with NSAIDs — if ≥4 features present, sensitivity 70%, specificity 82% for inflammatory back pain"]','A','Inflammatory back pain criteria (ASAS): onset <45 years, insidious onset, improvement with exercise, no improvement with rest, and nocturnal pain that improves on getting up. Meeting ≥4 criteria identifies axial SpA with good sensitivity/specificity. This initiates further investigation (HLA-B27, MRI sacroiliac joints).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Seronegative Spondyloarthropathies','medium','flashcard','What is enthesitis, and at which sites does it typically occur in SpA?','["Inflammation at tendon/ligament insertion into bone; common sites: Achilles tendon insertion (calcaneum), plantar fascia origin, iliac crest, ischial tuberosity, greater trochanter, lateral epicondyle, rotator cuff insertions — causes local pain and tenderness"]','A','Enthesitis is a hallmark of SpA pathology, distinct from the synovitis of RA. It produces localised tenderness at bony insertions and may cause periosteal reaction on X-ray. Plantar fasciitis and Achilles enthesopathy in SpA respond poorly to local steroid injections alone — systemic therapy is often required.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Seronegative Spondyloarthropathies','medium','flashcard','What is the most common extra-articular manifestation of ankylosing spondylitis?','["Acute anterior uveitis (iritis) — occurs in 25–40% of AS patients; presents with acute painful red eye, photophobia, blurred vision, small pupil; requires urgent ophthalmological assessment and topical corticosteroids to prevent posterior synechiae"]','A','Anterior uveitis in AS is typically unilateral, recurrent, and acute. It correlates with HLA-B27 positivity. It can precede or follow the onset of AS. Delay in treatment risks posterior synechiae formation (adhesion of iris to lens), cataract, and glaucoma. Systemic AS therapy does not reliably prevent uveitis recurrences.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Seronegative Spondyloarthropathies','medium','flashcard','Describe the treatment escalation in ankylosing spondylitis.','["1) NSAIDs (first-line — adequate trial of 2 NSAIDs at full dose ≥4 weeks each); 2) If axial disease — TNF inhibitors (etanercept, adalimumab, golimumab, certolizumab) or IL-17A inhibitors (secukinumab); 3) Physiotherapy throughout; 4) Note: DMARDs (MTX, SSZ) not effective for axial disease"]','A','Unlike RA, conventional DMARDs (methotrexate, sulfasalazine) are ineffective for axial SpA. NSAIDs remain the backbone of treatment and are continued even when biologics are started. Sulfasalazine may help peripheral joint and enthesitis involvement. Biologics have dramatically improved outcomes in refractory AS.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Seronegative Spondyloarthropathies','hard','flashcard','What are the five clinical patterns of psoriatic arthritis?','["1) Asymmetric oligoarthritis (<5 joints — most common); 2) Symmetric polyarthritis (RA-like); 3) DIP joint predominant; 4) Axial disease (sacroiliitis/spondylitis); 5) Arthritis mutilans (severe destructive — ''opera glass deformity'')"]','A','PsA presents in multiple clinical patterns. DIP involvement with nail disease is pathognomonic. Arthritis mutilans (pencil-in-cup deformity on X-ray, telescoping digits) is the most destructive form. Dactylitis (''sausage digit'' — diffuse swelling of entire digit) is characteristic of PsA and reactive arthritis.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Seronegative Spondyloarthropathies','hard','flashcard','What is dactylitis and which conditions cause it?','["Dactylitis = diffuse swelling of an entire digit (''sausage finger or toe'') due to simultaneous tendon sheath inflammation and joint synovitis; occurs in psoriatic arthritis and reactive arthritis — a key distinguishing feature from RA"]','A','Dactylitis results from combined flexor tenosynovitis and IP joint synovitis, causing the characteristic ''sausage digit.'' It is a clinical hallmark of PsA and reactive arthritis (and also seen in sickle cell disease — from vaso-occlusion). Detection of dactylitis should prompt evaluation for SpA.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Seronegative Spondyloarthropathies','easy','flashcard','What organisms trigger reactive arthritis, and what is the classic triad?','["Urogenital: Chlamydia trachomatis; Enteric: Salmonella, Shigella, Campylobacter, Yersinia; Classic triad: arthritis + urethritis/cervicitis + conjunctivitis (Reiter''s triad — can''t see, can''t pee, can''t climb a tree)"]','A','Reactive arthritis typically presents 1–4 weeks after the triggering infection. The arthritis is asymmetric, oligoarticular, and predominantly affects large lower limb joints. It is usually self-limiting (3–12 months) but 20–30% develop chronic arthritis. HLA-B27 predicts more severe and chronic disease.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Seronegative Spondyloarthropathies','medium','flashcard','What are the modified New York criteria for diagnosing established ankylosing spondylitis?','["Clinical: 1) Low back pain >3 months improved by exercise; 2) Limited lumbar spinal motion; 3) Limited chest expansion; Radiological: bilateral sacroiliitis grade II–IV OR unilateral grade III–IV; Need radiological criterion + ≥1 clinical criterion"]','A','The 1984 modified New York criteria require radiographic sacroiliitis. Before radiographic changes appear (early AS), the ASAS criteria using MRI (bone marrow oedema on STIR sequences indicating active sacroiliitis) are used to classify non-radiographic axial SpA — which is now treated with the same biologics.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Seronegative Spondyloarthropathies','hard','flashcard','How does Harrison''s describe psoriatic arthritis in terms of its pathological classification?','["Harrison''s describes PsA as an inflammatory musculoskeletal disease with both autoimmune and autoinflammatory features — unlike RA (primarily autoimmune) or gout (primarily autoinflammatory); driven by IL-17/IL-23 axis and TNF pathways"]','A','PsA has features of both autoimmune (T-cell mediated, adaptive immunity) and autoinflammatory (innate immunity, cytokine-mediated like IL-17, IL-23, TNF) disease. This dual pathogenesis explains why treatments targeting both pathways (TNF inhibitors, IL-12/23 inhibitors, IL-17 inhibitors) are effective in PsA.','universal',false,'{year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Septic Arthritis — Emergency Management','easy','flashcard','What does the Ghana STG 2017 say about clinical suspicion and treatment initiation in septic arthritis?','["Ghana STG: ''A hot swollen joint should be regarded as septic arthritis until proven otherwise''; if clinical suspicion is high, treat as septic arthritis even in the absence of fever; do not wait for culture results — treat empirically immediately"]','A','This guidance from the Ghana STG reflects the severity of septic arthritis (11% case fatality) and the risk of irreversible joint damage with delay. The diagnostic threshold is low and empirical treatment is the standard — cultures are collected but must not delay antibiotics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Septic Arthritis — Emergency Management','easy','flashcard','What is the first-line empiric antibiotic for acute septic arthritis/osteomyelitis per the Ghana STG 2017?','["1st line: Cloxacillin IV 500 mg 6-hourly (adults) for 2–4 weeks PLUS Ciprofloxacin IV 400 mg 8–12 hourly for 14 days; 2nd line (penicillin allergy): Clindamycin IV 300 mg 6-hourly PLUS Gentamicin IV 40–80 mg 8-hourly (monitor renal/auditory function)"]','A','The combination of cloxacillin (covers Staphylococci — the most common pathogen) and ciprofloxacin (covers Gram-negative organisms including Salmonella in sickle cell disease and Haemophilus) provides broad empiric coverage for acute orthopaedic infections as per Ghana STG 2017, Chapter 23.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Septic Arthritis — Emergency Management','medium','flashcard','Which organisms cause acute osteomyelitis/septic arthritis in patients with sickle cell disease, and how does treatment differ?','["Additional cover needed for Salmonella spp.; Ghana STG: Cloxacillin IV + Ciprofloxacin IV (Ciprofloxacin covers Salmonella); 2nd line: Clindamycin IV + Ciprofloxacin; Amoxicillin-clavulanate is an alternative for penicillin-tolerant patients"]','A','Patients with sickle cell disease have functional asplenia (impaired opsonisation), making them susceptible to encapsulated organisms and Salmonella. Salmonella osteomyelitis in sickle cell is classically multifocal and affects diaphyses. The Ghana STG provides specific regimens for this patient group.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Septic Arthritis — Emergency Management','medium','flashcard','What synovial fluid WBC count and differential strongly suggests septic arthritis?','[">50,000 cells/µL with >90% polymorphonuclear leucocytes (PMNs/neutrophils) strongly suggests septic arthritis; Gram stain positive in ~60%; culture positive in ~80–90% of non-gonococcal cases; note: gout/pseudogout can occasionally reach these counts"]','A','Synovial fluid analysis is the cornerstone of diagnosing septic arthritis. The WBC threshold of >50,000 cells/µL is classically cited, though values as low as 25,000 can indicate sepsis in immunosuppressed patients. Critically, gout and pseudogout can also cause high WBC counts — crystal analysis differentiates.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Septic Arthritis — Emergency Management','medium','flashcard','What non-pharmacological intervention is required alongside antibiotics in septic arthritis management?','["Joint washout/drainage: serial needle aspiration (daily) for accessible joints (knee) or arthroscopic washout or open surgical drainage (hip/shoulder/inaccessible joints); removes bacterial load, toxins, proteolytic enzymes; splinting for comfort"]','A','Adequate drainage is essential for cure in septic arthritis. The knee can often be managed with serial needle aspiration (daily until no re-accumulation). The hip, shoulder, and other inaccessible joints typically require arthroscopic or open drainage. The Ghana STG lists ''incision and drainage'' and ''ultrasound-guided aspiration'' as non-pharmacological management.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Septic Arthritis — Emergency Management','hard','flashcard','What is sequestrectomy and when is it used in musculoskeletal infection?','["Sequestrectomy = surgical removal of the sequestrum (avascular dead bone) in chronic osteomyelitis; dead bone acts as a nidus for infection inaccessible to antibiotics; also: saucerisation (removal of involucrum cortex to expose medullary cavity) and implant removal for infected prosthetics"]','A','In chronic osteomyelitis, necrotic bone (sequestrum) is isolated by new periosteal bone (involucrum). Antibiotics cannot penetrate avascular bone. Sequestrectomy removes the nidus. The Ghana STG 2017 includes this alongside wound dressing, splinting, and implant removal as surgical interventions for chronic osteomyelitis.','universal',true,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Septic Arthritis — Emergency Management','hard','flashcard','Which investigations are recommended by the Ghana STG 2017 before starting antibiotics for acute osteomyelitis/septic arthritis?','["FBC, ESR, CRP; sickling test; blood culture (before antibiotics); X-ray and ultrasound of affected part (for guided aspiration); Gram stain and culture of aspirate; MRI if available; radionuclide scan; monitor BUE and creatinine and weekly auditory tests if on gentamicin"]','A','The Ghana STG investigation panel for acute orthopaedic infection is comprehensive. Blood cultures before antibiotics are critical but must not delay treatment. CRP/ESR monitor treatment response. Ultrasound guides aspiration (especially in children). MRI is most sensitive for early osteomyelitis before X-ray changes appear.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Septic Arthritis — Emergency Management','easy','flashcard','What are the most common routes of infection causing osteomyelitis?','["Most common: haematogenous spread (bacteraemia seeding metaphyseal bone — especially in children); Direct inoculation (open fractures, surgery, joint aspiration); Contiguous spread (from adjacent soft tissue infection, diabetic foot ulcer)"]','A','The Ghana STG notes the commonest route is haematogenous spread, often from skin lesions and ENT infections. In children, haematogenous osteomyelitis typically affects the metaphyses of long bones (rich blood supply, sluggish flow). In adults, vertebral osteomyelitis is more common via the haematogenous route.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Septic Arthritis — Emergency Management','medium','flashcard','When should a patient with chronic osteomyelitis in Ghana be referred per the Ghana STG 2017?','["All patients with chronic osteomyelitis should be referred as soon as possible to an orthopaedic specialist, as surgical intervention (sequestrectomy, wound debridement, implant removal) is typically required alongside antibiotic therapy"]','A','The Ghana STG 2017 states: "All patients should be referred as soon as possible to an orthopaedic specialist" for chronic osteomyelitis. This reflects the complexity of chronic infection — requiring imaging (CT scan, X-ray), surgical planning, prolonged antibiotic courses (IV then oral), and wound management.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Septic Arthritis — Emergency Management','hard','flashcard','How does acute septic arthritis differ from reactive arthritis in terms of joint fluid and treatment?','["Septic: WBC >50,000/µL PMN-predominant, positive culture/Gram stain, requires IV antibiotics and joint drainage; Reactive: WBC 10,000–50,000/µL, sterile culture, follows preceding GU/enteric infection, self-limiting, NSAIDs and physiotherapy — antibiotics for any active concurrent STI"]','A','This distinction is clinically critical. Reactive arthritis is a sterile inflammatory arthritis triggered by infection at a distant site — joint fluid is culture-negative. Treating reactive arthritis as septic arthritis with IV antibiotics is wrong; treating septic arthritis as reactive with NSAIDs only is potentially fatal.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Back Pain — Clinical Approach','easy','flashcard','List six red flags in back pain that require urgent investigation.','["1) Bladder/bowel dysfunction (cauda equina); 2) Saddle anaesthesia; 3) Age >50 or <20 at onset; 4) History of malignancy; 5) Unexplained weight loss/fever; 6) Night pain/pain at rest not relieved by position; 7) Severe progressive neurological deficit; 8) Recent trauma; 9) Immunosuppression/IV drug use"]','A','Red flags prompt urgent imaging (MRI) and specialist referral. Cauda equina syndrome requires emergency MRI and surgical decompression within hours. Malignancy-related MSCC is an oncological emergency requiring dexamethasone and radiotherapy/surgery. Most acute back pain (no red flags) resolves within 6 weeks with conservative care.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Back Pain — Clinical Approach','easy','flashcard','What is cauda equina syndrome and why is it a surgical emergency?','["Cauda equina syndrome = compression of the cauda equina nerve roots (below L1-2) causing saddle anaesthesia, bilateral leg weakness, urinary retention (overflow incontinence), and loss of anal tone; surgical emergency — delay causes permanent bladder, bowel, and sexual dysfunction"]','A','The cauda equina is the bundle of nerve roots in the lumbar vertebral canal below the conus medullaris (L1-2). Compression (large central disc prolapse, tumour, abscess, haematoma) causes irreversible sphincter and motor deficits without urgent surgical decompression. MRI is the investigation of choice.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Back Pain — Clinical Approach','medium','flashcard','Describe the clinical features of L4, L5, and S1 nerve root compression.','["L4: knee jerk absent/reduced, weak knee extension (quad), medial leg numbness; L5: ankle dorsiflexion + great toe extension weakness, dorsal foot numbness, ankle jerk preserved; S1: ankle jerk absent, plantarflexion weak, lateral foot/sole numbness"]','A','L4-L5 (L5 root) and L5-S1 (S1 root) disc herniations are the most common. The straight leg raise is positive for L4-5 and L5-S1 involvement. The femoral stretch test (prone, hip extension) tests L2, L3, L4 nerve roots from upper lumbar disc herniations.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Back Pain — Clinical Approach','medium','flashcard','How does neurogenic claudication (spinal stenosis) differ from vascular claudication?','["Neurogenic: worsened by walking AND spinal extension (standing upright, walking downhill); relieved by sitting, bending forward, or cycling; normal peripheral pulses; Vascular: worsened by walking, relieved by standing still; reduced peripheral pulses, ABI <0.9"]','A','This distinction is critical in older patients. Neurogenic claudication from lumbar spinal stenosis causes leg pain, heaviness, and paraesthesia that worsens with extension (narrows the spinal canal) and improves with flexion (widens canal). Patients can often cycle (flexed position) despite severe walking limitation.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Back Pain — Clinical Approach','medium','flashcard','What is the first-line management of acute non-specific low back pain (<6 weeks)?','["Reassurance (excellent prognosis — 90% resolve in 6 weeks), advise staying active (avoid bed rest), simple analgesia (paracetamol ± NSAIDs), physiotherapy/exercise; imaging NOT indicated without red flags"]','A','Bed rest is counterproductive in LBP — activity maintains disc nutrition and prevents deconditioning. NSAIDs reduce inflammatory pain. Physiotherapy addresses muscle weakness and posture. Imaging in acute non-specific LBP rarely changes management and may reinforce pain behaviour by over-medicalising a self-limiting condition.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Back Pain — Clinical Approach','hard','flashcard','How is discal back pain distinguished from facet joint pain on clinical grounds?','["Discal: worse with flexion/sitting/coughing/sneezing/Valsalva; may radiate to buttocks or leg (sciatica); relieved by extension; Facet: worse with extension and rotation, refers to buttock/posterior thigh (not below knee), no neurological deficit, relieved by flexion/walking"]','A','Facet joint pain is pure axial/referred pain — no true dermatomal radiation below the knee. Discal pain with annular tear can be purely axial but with radiculopathy extends below knee. Provocative testing (facet loading with extension-rotation) and response to facet joint injections can help distinguish.','universal',false,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Back Pain — Clinical Approach','hard','flashcard','What is the Schober''s test and what does it assess?','["Schober''s test: mark L5 level (dimples of Venus), mark 10 cm above and 5 cm below; ask patient to flex maximally; normal increase ≥5 cm (total 20 cm); <5 cm increase indicates restricted lumbar flexion, suggesting ankylosing spondylitis or lumbar spinal fusion"]','A','Schober''s test quantifies lumbar spinal mobility. It is used specifically in suspected ankylosing spondylitis — limited lumbar flexion is one of the modified New York criteria for AS diagnosis. Serial measurements can track progression of axial involvement and response to treatment.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Back Pain — Clinical Approach','easy','flashcard','What are the clinical features of sciatica (lumbar radiculopathy)?','["Pain radiating from buttock/back down posterior or lateral leg, below the knee, in a dermatomal distribution; associated paraesthesia, numbness, or weakness; positive straight leg raise (reproduces leg pain at <70° elevation); may include motor deficit/reflex change at affected level"]','A','True sciatica involves sciatic nerve root compression (L4, L5, or S1 most commonly) causing radicular pain. Referred pain from facet joints or sacroiliac joints can mimic sciatica but typically does not radiate below the knee and lacks neurological signs. Most sciatica resolves within 6–12 weeks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Back Pain — Clinical Approach','medium','flashcard','In a patient with back pain and known malignancy, what is metastatic spinal cord compression (MSCC) and how is it managed?','["MSCC: vertebral metastasis compresses spinal cord or cauda equina — back pain + progressive paraparesis/sensory level ± sphincter dysfunction; Emergency: high-dose dexamethasone 8–16 mg IV stat then oral; urgent MRI whole spine; radiotherapy (most common) or surgical decompression ± stabilisation"]','A','MSCC is an oncological emergency. High-dose dexamethasone reduces cord oedema and is given immediately on clinical suspicion before imaging is confirmed. The most common primary cancers: prostate, breast, lung, myeloma, renal. Prognosis is best when treated before complete paralysis — ambulatory status at presentation is the strongest prognostic factor.','universal',true,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Back Pain — Clinical Approach','hard','flashcard','What are the yellow flags in back pain and why do they matter?','["Yellow flags = psychosocial factors predicting chronic disability: negative beliefs (''pain means damage''), catastrophising, fear-avoidance behaviour, job dissatisfaction, depression/anxiety, passive coping strategies, litigation; address with CBT, graded exercise, multidisciplinary rehabilitation"]','A','Yellow flags identify patients at risk of transitioning from acute to chronic back pain (>12 weeks) and long-term disability. Addressing psychosocial factors early through cognitive-behavioural therapy and graded activity programmes is more effective than passive treatments. Failure to address yellow flags is the main cause of treatment failure.','universal',false,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','MSK Emergencies','easy','flashcard','What are the 6 Ps of acute compartment syndrome?','["Pain (out of proportion to injury, worsened by passive stretch), Pressure (tense compartment), Paraesthesia, Pallor, Pulselessness, Paralysis — early signs: pain and paraesthesia; late signs: pallor, pulselessness, paralysis (indicate irreversible ischaemia)"]','A','The 6 Ps guide clinical diagnosis of compartment syndrome. Importantly, pulselessness and paralysis are LATE signs indicating irreversible ischaemia and permanent damage. Diagnosis and fasciotomy must not wait for these signs — pain out of proportion and paraesthesia are the critical early triggers for action.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','MSK Emergencies','easy','flashcard','What is the definitive treatment of acute compartment syndrome and what is the time window?','["Emergency fasciotomy — surgical incision of the investing fascia of the compartment(s); must be performed within 6 hours of onset to prevent irreversible muscle necrosis; all casts and constricting dressings removed immediately; measure compartment pressures if diagnosis uncertain"]','A','Fasciotomy involves longitudinal incisions through the skin and fascia over all affected compartments (e.g., all four compartments of the lower leg). Wounds are left open and closed by delayed primary closure or skin grafting. Delay beyond 6–8 hours results in Volkmann''s ischaemic contracture and permanent disability.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','MSK Emergencies','medium','flashcard','What is the classic presentation of rhabdomyolysis and how is it managed?','["Presentation: muscle pain/weakness, dark red-brown (''cola-coloured'') urine, massively elevated CK (>10,000 U/L); triggers: crush injury, prolonged immobility, severe exercise, statins, myopathies, seizures; Management: aggressive IV fluid (Normal saline 1–1.5 L/hr), target urine output >200 mL/hr, monitor K⁺, creatinine, Ca²⁺ — dialysis if refractory AKI"]','A','Rhabdomyolysis causes AKI via myoglobin tubular toxicity, cast formation (especially in acidic urine), and direct tubular ischaemia. Treatment cornerstone is early, aggressive IV hydration to maintain high urine flow. Bicarbonate alkalinisation may reduce myoglobin precipitation but lacks strong RCT evidence. Hyperkalaemia can be immediately life-threatening.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','MSK Emergencies','medium','flashcard','What is fat embolism syndrome (FES) and when does it occur?','["FES occurs 24–72 hours after long bone fractures (especially femur/tibia) or orthopaedic surgery; Classic triad: 1) Hypoxaemia (PaO2 <60 mmHg); 2) Neurological dysfunction (confusion, drowsiness); 3) Petechial rash (conjunctivae, axillae, upper chest); Treatment: supportive — oxygen/ventilation, early fracture stabilisation prevents FES"]','A','Fat emboli from bone marrow fat enter pulmonary circulation causing ARDS-like picture. The petechial rash (fat globules in skin capillaries) is pathognomonic — it appears on day 2–3 and may be fleeting. Early internal fixation of long bone fractures reduces fat release and FES incidence compared to prolonged traction.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','MSK Emergencies','medium','flashcard','Which electrolyte abnormalities occur in rhabdomyolysis and what are their consequences?','["Hyperkalaemia (massive intracellular K⁺ release — cardiac arrest risk); Hyperphosphataemia (cell lysis); Hypocalcaemia acute (Ca²⁺ deposited in muscle, reciprocal to high phosphate — tetany); Hyperuricaemia; Late hypercalcaemia (calcium mobilised from muscle deposits during recovery)"]','A','The metabolic consequences of rhabdomyolysis are complex and biphasic. Acute hyperkalaemia is the most dangerous immediate complication. The paradoxical acute hypocalcaemia usually resolves and should not be treated unless symptomatic (as calcium supplements can worsen tissue calcification). Late hypercalcaemia during recovery is from mobilisation of muscle calcium deposits.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','MSK Emergencies','hard','flashcard','At what compartment pressure or differential pressure (ΔP) is fasciotomy indicated?','["Fasciotomy indicated when: compartment pressure >30 mmHg (absolute threshold) OR ΔP (diastolic BP − compartment pressure) <30 mmHg (more clinically relevant as accounts for perfusion pressure); measurement with Whitesides technique or commercial monitor"]','A','The ΔP threshold is preferred clinically as it integrates the patient''s blood pressure. A hypotensive patient with compartment pressure of 25 mmHg may have ΔP <30 mmHg and still require fasciotomy. Normal compartment pressure is 0–8 mmHg. Pressure is measured with a needle manometer inserted into the compartment.','universal',true,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','MSK Emergencies','hard','flashcard','What is Volkmann''s ischaemic contracture and how does it relate to compartment syndrome?','["Volkmann''s ischaemic contracture = irreversible fibrosis and contracture of forearm muscles (flexor compartment) resulting from untreated or delayed treatment of anterior forearm compartment syndrome; presents with finger flexion, wrist flexion, pronation deformity — loss of hand function"]','A','Volkmann''s contracture is the classic late consequence of missed compartment syndrome in the forearm (typically after supracondylar fracture in children). Muscle ischaemia leads to necrosis and fibrotic replacement within 6–8 hours. Prevention requires early recognition and fasciotomy; treatment is complex reconstructive surgery.','universal',true,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','MSK Emergencies','easy','flashcard','What is the earliest clinical sign of acute compartment syndrome?','["Pain out of proportion to the injury AND pain on passive stretch of muscles within the affected compartment — these are the earliest and most reliable signs, preceding pallor, pulselessness, and paralysis (which are late, indicating irreversible ischaemia)"]','A','Pain on passive muscle stretch is the key early diagnostic sign. For anterior tibial compartment syndrome, passive plantarflexion of the toes stretches the anterior compartment muscles and reproduces or worsens pain. This should be tested in any patient with high-risk injuries (tibial fractures, circumferential burns, tight casts).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','MSK Emergencies','medium','flashcard','What common medications can precipitate rhabdomyolysis?','["Statins (especially with CYP3A4 inhibitors like clarithromycin, diltiazem, grapefruit — increase statin levels causing myopathy/rhabdomyolysis); also: fibrates combined with statins; cocaine; antipsychotics (NMS); alcohol; colchicine (in renal failure)"]','A','Statin-induced rhabdomyolysis is dose-related and risk is highest with lovastatin, simvastatin, and atorvastatin (CYP3A4 metabolised). Combinations with gemfibrozil, macrolide antibiotics, azole antifungals, or cyclosporine dramatically increase risk. Patients presenting with myalgia on statins should have urgent CK checked.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','MSK Emergencies','hard','flashcard','Describe the Gurd criteria for diagnosing fat embolism syndrome.','["Major criteria (1 required): petechial rash, respiratory insufficiency, cerebral involvement; Minor criteria (4 required if no major): fever >38.5°C, tachycardia >110, retinal changes, jaundice, renal oliguria, anaemia, thrombocytopaenia, high ESR, fat globules in sputum/urine; 1 major + 4 minor OR 2 major required"]','A','The Gurd criteria formalise diagnosis of FES, which is otherwise clinical. The petechial rash is the most specific finding. Pulmonary fat embolism causes hypoxaemia and can progress to ARDS. Management is supportive — early fracture stabilisation (intramedullary nailing) is the key preventative measure.','universal',false,'{year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Perioperative MSK Management','easy','flashcard','What are the recommended durations of pharmacological DVT prophylaxis after joint arthroplasty?','["Total knee arthroplasty: 10–14 days; Total hip arthroplasty: 28–35 days (extended prophylaxis due to higher VTE risk); Agents: LMWH (enoxaparin 40 mg SC daily) or DOAC (rivaroxaban, apixaban); mechanical compression stockings as adjunct"]','A','Hip arthroplasty carries higher VTE risk than knee arthroplasty due to the proximity to pelvic veins and greater immobility. Pulmonary embolism remains a leading cause of perioperative death. Extended prophylaxis to 35 days post-THR is supported by NICE, ACCP, and orthopaedic guidelines.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Perioperative MSK Management','easy','flashcard','What is the current recommendation for methotrexate management perioperatively in RA patients?','["Continue methotrexate through the perioperative period for elective orthopaedic surgery — evidence shows no increased surgical infection risk with MTX continuation; stopping MTX risks disease flare; in contrast, biologics (TNF inhibitors) are withheld"]','A','Multiple studies and ACR/EULAR guidance support MTX continuation perioperatively. The perioperative infection risk from DMARDs is primarily from biologics (immunosuppressive) rather than conventional DMARDs at standard doses. Disease flares from stopping DMARDs can be more harmful than the small theoretical infection risk.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Perioperative MSK Management','medium','flashcard','How should warfarin be managed perioperatively for a patient requiring elective joint replacement?','["Stop warfarin 5 days preoperatively (to allow INR to normalise <1.5); bridge with therapeutic LMWH if high thromboembolic risk (mechanical heart valve, AF with CHA2DS2-VASc ≥3, recent VTE); restart warfarin postoperatively with LMWH bridge until therapeutic INR achieved; check INR day of surgery"]','A','The bridging decision is risk-stratified: high-risk patients (mechanical valve, recent VTE <3 months) need LMWH bridging; low-to-moderate risk (AF without prior stroke) can stop warfarin without bridging. DOACs are stopped 24–48 hours preoperatively (48–72 hours for renal impairment/dabigatran) without bridging.','universal',true,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Perioperative MSK Management','medium','flashcard','What is stress dosing of corticosteroids and when is it needed?','["Patients on chronic corticosteroids (≥5 mg prednisolone daily for ≥3 months) have HPA axis suppression and cannot mount cortisol stress response to surgery; Stress dosing: hydrocortisone 50–100 mg IV at induction, then 25–50 mg IV 8-hourly for 24–48 hours; prevents adrenal crisis (hypotension, hyponatraemia, hypoglycaemia)"]','A','Adrenal crisis in the perioperative period presents with hypotension refractory to fluids, hyponatraemia, and hypoglycaemia. It can be fatal if not recognised. The degree of HPA suppression correlates with daily dose and duration of steroids. Single dose <5 mg or alternate-day regimens carry lower risk.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Perioperative MSK Management','medium','flashcard','Why do TNF inhibitors increase surgical infection risk, and how long should they be withheld before surgery?','["TNF inhibitors impair innate immunity — neutrophil and macrophage function reduced; risk of bacterial (including TB) and opportunistic infection; withhold for 1 drug half-life before surgery: etanercept ~1 week, adalimumab/certolizumab ~2 weeks, infliximab ~4–8 weeks (dosing interval-based); resume when wound healed (typically 2 weeks post-op)"]','A','The timing of TNF inhibitor withdrawal is based on pharmacokinetics. After 1 half-life, drug concentration falls by 50%. ACR/EULAR guidelines recommend withholding for the equivalent of one dosing interval before surgery. The decision must balance infection risk against disease flare risk.','universal',true,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Perioperative MSK Management','hard','flashcard','What is the perioperative significance of atlantoaxial subluxation in RA for the anaesthetist?','["Atlantoaxial subluxation (C1-C2 instability from erosion of transverse ligament/odontoid peg) risks spinal cord compression during neck extension for direct laryngoscopy/intubation; Assessment: pre-operative flexion-extension cervical X-ray; Management: awake fibreoptic intubation with neck in neutral position, or video laryngoscopy; inform anaesthetist of RA diagnosis"]','A','All patients with RA scheduled for general anaesthesia should be assessed for cervical spine disease. Flexion-extension X-rays are recommended for elective procedures. If atlantoaxial subluxation is confirmed, awake fibreoptic intubation keeps the neck neutral and allows neurological monitoring throughout intubation.','universal',true,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Perioperative MSK Management','hard','flashcard','Which patient factors increase the risk of prosthetic joint infection (PJI) after total joint arthroplasty?','["High-risk factors: diabetes mellitus (impaired neutrophil function), obesity (BMI >40), active RA/immunosuppression, previous joint infection, malnourishment, renal/hepatic failure, smoking, prior revision surgery; Strategy: optimise modifiable risk factors pre-op; give cefazolin IV within 60 min of incision; MRSA carriers: vancomycin added"]','A','PJI is a devastating complication of arthroplasty with high morbidity. Pre-operative optimisation includes glycaemic control, smoking cessation, weight loss, and eradicating remote infections. Mupirocin nasal decolonisation and chlorhexidine washes for MRSA carriers reduce SSI rates. Antibiotic prophylaxis targets Staphylococci (cefazolin or cefuroxime).','universal',true,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Perioperative MSK Management','easy','flashcard','What are the three components of Virchow''s triad explaining VTE risk in orthopaedic surgery?','["1) Venous stasis (immobility, tourniquets, limb elevation); 2) Endothelial injury (surgical dissection, bone cement, instrumentation); 3) Hypercoagulability (surgical stress response, tissue factor release, platelet activation) — all three operate simultaneously in major joint replacement"]','A','Virchow''s triad predicts VTE. In major orthopaedic surgery, all three elements are present: stasis from immobility/positioning, endothelial damage from surgical dissection, and a hypercoagulable surgical stress state with elevated fibrinogen, Factor VIII, and platelet reactivity. This explains the very high VTE incidence without prophylaxis.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Perioperative MSK Management','medium','flashcard','When should NSAIDs be stopped before elective orthopaedic surgery?','["Non-selective NSAIDs: stop 5–7 days preoperatively (platelet inhibition duration matches platelet lifespan); Aspirin (irreversible COX-1 inhibitor): stop 7–10 days unless aspirin prescribed for cardiovascular protection (cardiology review needed); COX-2 inhibitors: no platelet effect — can continue to within 24 hours of surgery"]','A','NSAIDs inhibit platelet thromboxane A2 (COX-1) reversibly — new platelets restore haemostasis within 5–7 days. Aspirin''s COX-1 inhibition is irreversible for platelet lifetime (~10 days). COX-2 selective inhibitors (celecoxib) spare platelet COX-1 and do not increase bleeding risk, making them useful perioperatively for analgesia.','universal',false,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Perioperative MSK Management','hard','flashcard','What is enhanced recovery after surgery (ERAS) and how does it apply to joint arthroplasty?','["ERAS protocol for joint arthroplasty: preoperative optimisation (anaemia, nutrition), multimodal analgesia (avoid opioids — use paracetamol, NSAIDs, local infiltration), spinal anaesthesia preferred, early mobilisation (day of surgery), VTE prophylaxis, restrictive transfusion, goal-directed fluid therapy — reduces LOS and complications"]','A','ERAS protocols have transformed arthroplasty outcomes. Key elements include: preoperative carbohydrate loading, regional anaesthesia, minimising opioids (reduces ileus, nausea, dizziness), peri-articular local anaesthetic infiltration, early physiotherapy from day of surgery, and avoiding unnecessary urinary catheters. LOS has fallen from 5–7 days to 1–3 days.','universal',false,'{year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Crystal Arthropathy — Differential Diagnosis','easy','flashcard','Compare the crystals of gout and pseudogout on polarised light microscopy.','["Gout (MSU): needle-shaped, NEGATIVELY birefringent (yellow parallel to compensator = negative); Pseudogout (CPPD): rhomboid or rod-shaped, WEAKLY POSITIVELY birefringent (blue parallel to compensator = positive); Mnemonic: ''Gout = Needles Negative; Pseudogout = Rhomboid Positive''"]','A','The birefringence distinction is fundamental: negative = gout, positive = pseudogout. On polarised microscopy with a red compensator: MSU crystals appear yellow when aligned with the compensator axis (negative birefringence); CPPD crystals appear blue in the same orientation (positive birefringence). This must be performed on fresh synovial fluid.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Crystal Arthropathy — Differential Diagnosis','easy','flashcard','Which joint does pseudogout (CPPD) most commonly affect, and how does this differ from gout?','["Pseudogout: knee most commonly (60–70% of attacks); Gout: first MTP joint (podagra) classically first — also ankle, knee, wrist; Pseudogout attacks are more prolonged than gout and affect mainly older women; both present as acute monoarthritis with joint effusion"]','A','The Ghana STG notes CPPD attacks ''persist longer and affect the knee most commonly'' distinguishing it from classical gout. Both can cause acute painful monoarthritis with effusion. The distinction has major treatment implications: gout is managed with NSAIDs/colchicine and urate-lowering; CPPD is treated symptomatically with no crystal-depleting drug.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Crystal Arthropathy — Differential Diagnosis','medium','flashcard','What radiological finding on plain X-ray is characteristic of CPPD crystal deposition?','["Chondrocalcinosis = calcification within fibrocartilage (menisci of knee, TFCC of wrist, symphysis pubis) and hyaline articular cartilage — appears as linear or stippled calcification parallel to the articular surface; seen on plain X-ray; can affect multiple joints simultaneously"]','A','Chondrocalcinosis on X-ray is the hallmark of CPPD deposition. The menisci (knee), triangular fibrocartilage complex (wrist), symphysis pubis, and intervertebral discs are commonly affected. However, not all chondrocalcinosis is symptomatic, and symptomatic CPPD can occur without visible chondrocalcinosis.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Crystal Arthropathy — Differential Diagnosis','medium','flashcard','What metabolic conditions are associated with secondary CPPD crystal deposition and should be screened for?','["Hyperparathyroidism (most common secondary cause), haemochromatosis, hypomagnesaemia, hypothyroidism, hypophosphatasia, Wilson''s disease, gout (co-existent) — check: calcium, PTH, serum ferritin, transferrin saturation, Mg²⁺, thyroid function in atypical or younger patients with CPPD"]','A','Secondary CPPD in patients under 60, or with polyarticular involvement, should trigger a metabolic screen. Hyperparathyroidism raises calcium and promotes CPPD; haemochromatosis causes iron deposition in cartilage; hypomagnesaemia impairs pyrophosphatase activity. Treatment of the underlying disorder may reduce CPPD attacks.','universal',true,'{year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Crystal Arthropathy — Differential Diagnosis','medium','flashcard','How is the hot swollen joint differential diagnosed — septic vs gout vs pseudogout?','["Septic: fever, high WBC (>50,000 PMN-predominant), +ve culture/Gram stain, no crystals — IV antibiotics + drainage; Gout: negative birefringent needle MSU crystals, high uric acid (may be normal during attack) — NSAIDs/colchicine; CPPD: positive birefringent rhomboid crystals, chondrocalcinosis on X-ray — NSAIDs/colchicine; Note: septic arthritis and crystal arthritis can co-exist"]','A','The Ghana STG emphasises the differential diagnosis of the hot swollen joint as an emergency (septic arthritis case fatality 11%). Synovial fluid analysis is critical. If clinical suspicion of sepsis is high, treat empirically while awaiting culture. Crystals do not exclude septic arthritis — both can co-exist.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Crystal Arthropathy — Differential Diagnosis','hard','flashcard','What is hydroxyapatite (basic calcium phosphate) crystal disease and what is its most common presentation?','["Hydroxyapatite (BCP) crystal deposits most commonly cause calcific tendinitis — especially supraspinatus/rotator cuff tendons causing acute severe shoulder pain with X-ray showing tendon calcification; Milwaukee shoulder syndrome = BCP-associated destructive shoulder arthropathy in elderly women; diagnosed by electron microscopy or alizarin red stain"]','A','BCP crystals are not birefringent and cannot be seen on standard polarised microscopy — require electron microscopy or special stains. Calcific tendinitis causes intense periarticular inflammation with dramatic X-ray calcification in the tendon. It can resolve spontaneously or require aspiration of calcific material, physiotherapy, or needling.','universal',false,'{year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Crystal Arthropathy — Differential Diagnosis','hard','flashcard','According to Harrison''s, what unusual clinical presentation can CPPD arthropathy mimic radiographically?','["Harrison''s states CPPD can cause severe destructive arthropathy that ''radiographically mimics neuropathic arthritis (Charcot joint)'' — with joint space loss, bone fragmentation, debris, and calcification; also mimics OA but with ''peculiar'' distribution and chondrocalcinosis"]','A','CPPD-induced destructive arthropathy (pseudoneuropathic arthritis) is clinically confusing as it may lack neurological findings expected with true Charcot joint. The X-ray shows rapid joint destruction, calcification, and bone fragmentation mimicking Charcot joint from diabetes or tabes dorsalis. A thorough neurological exam distinguishes the two.','universal',false,'{year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Crystal Arthropathy — Differential Diagnosis','easy','flashcard','What is the treatment of an acute CPPD (pseudogout) flare per the Ghana STG 2017?','["1st line: NSAIDs (Naproxen 250–500 mg 12-hourly, Celecoxib 400 mg stat then 200 mg 12–24 hourly, Diclofenac 50 mg 8-hourly, or Ibuprofen 200–800 mg 6–8 hourly); OR Colchicine 500 mcg 6–12 hourly; 2nd line: Intra-articular/oral prednisolone (consult specialist); unlike gout — no crystal-depleting therapy available"]','A','The Ghana STG 2017 (section 231) provides specific NSAIDs for CPPD flares with colchicine as an alternative. There is no equivalent of allopurinol for CPPD — no drug reduces CPPD crystal burden. Management is purely symptomatic. Treat any underlying metabolic disease.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Crystal Arthropathy — Differential Diagnosis','medium','flashcard','What is the synovial fluid WBC classification table for the four main types of joint disease?','["Normal: <200 cells/µL, clear, viscous; Non-inflammatory (OA): <2000 cells/µL, clear/yellow, high viscosity; Inflammatory (RA, crystal): 2000–50,000 cells/µL, turbid, low viscosity; Septic: >50,000 cells/µL (>90% PMN), purulent, very low viscosity, positive culture"]','A','This classification is the cornerstone of synovial fluid analysis. The absolute WBC count guides immediate management. WBC >50,000 mandates empirical antibiotics pending culture. Crystal analysis should be performed in all inflammatory fluids regardless of WBC. Glucose (low in septic vs serum) is a supplementary marker.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Clinicals','Crystal Arthropathy — Differential Diagnosis','hard','flashcard','What is the pathophysiology of calcium pyrophosphate crystal-induced inflammation?','["CPPD crystals are phagocytosed by neutrophils and activate the NLRP3 inflammasome, triggering IL-1β release — the same pathway as MSU crystals in gout; CPPD also stimulates synoviocytes and fibroblasts to release PGE2, IL-6, and collagenases, driving cartilage destruction and persistent inflammation"]','A','The NLRP3 inflammasome is the common pathway for both gout and pseudogout. IL-1β is the central mediator. This is why IL-1 inhibitors (anakinra, canakinumab) are effective in both conditions when colchicine and NSAIDs fail. CPPD crystals are less potent inflammasome activators than MSU, explaining their less intense but more prolonged attacks.','universal',false,'{year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
